<?php require "auth.php"; $msg=""; if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["nama"]??"");$harga=(float)($_POST["harga"]??0);$stok=(int)($_POST["stok"]??0);if($n!==""){$s=$conn->prepare("INSERT INTO barang(nama_barang,harga,stok) VALUES(?,?,?)");$s->bind_param("sdi",$n,$harga,$stok);$msg=$s->execute()?"Barang ditambahkan.":"Gagal menambah barang.";}} $rows=$conn->query("SELECT * FROM barang ORDER BY id DESC"); ?><!doctype html><html lang="id"><head><meta charset="utf-8"><link rel="stylesheet" href="style.css"><title>Barang</title></head><body><header><b>Kantin POS</b><nav><a href="dashboard.php">Dashboard</a><a href="barang.php">Barang</a><a href="kategori.php">Kategori</a><a href="transaksi.php">Transaksi</a><a href="logout.php">Keluar</a></nav></header><main class="wide"><section class="panel"><h1>Data Barang</h1><p><?=$msg?></p><form method="post"><label>Nama barang</label><input name="nama" required><label>Harga</label><input type="number" name="harga" min="0" required><label>Stok</label><input type="number" name="stok" min="0" required><button>Tambah Barang</button></form></section><section class="panel"><h2>Daftar Barang</h2><table><tr><th>Nama</th><th>Harga</th><th>Stok</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r["nama_barang"])?></td><td>Rp <?=number_format($r["harga"],0,",",".")?></td><td><?=$r["stok"]?></td></tr><?php endwhile;?></table></section></main></body></html>